"""Freeze source-only benchmark manifests; no evaluation/model execution."""
from pathlib import Path
import csv,hashlib,json,subprocess
P=Path(__file__).parent;S=P/'sources'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
release=json.loads((P/'FLEXIACT_RELEASE_INVENTORY.json').read_text());rev=release['release_revision'];tree={x['path']:x for x in json.loads((S/'flexiact_hf_retry').read_text()) if x['type']=='file'}
receipt=json.loads((P/'FLEXIACT_ASSET_RECEIPT.json').read_text());downloaded={x['path']:x for x in receipt['files']}; acts=['chest','crouch','fitness','one_leg','rotate'];pairs=[]
for row in release['pairs']:
 ref=f"benchmark/reference_videos/{row['group']}/{row['action']}.mp4";csvpath=S/f"flexiact_hf__benchmark__captions__{row['group']}__{row['action']}__val_image.csv"
 def asset(path):
  info=tree[path]
  return {'official_path':path,'pinned_url':'https://huggingface.co/datasets/shiyi0408/FlexiAct/resolve/'+rev+'/'+path,'bytes':info['size'],'official_lfs_sha256':info.get('lfs',{}).get('oid'),'downloaded':path in downloaded,'local_path':downloaded.get(path,{}).get('local_path')}
 pairs.append({'stable_id':row['stable_id'],'group':row['group'],'action':row['action'],'official_csv_row_zero_based':row['row'],'source':asset(ref),'target':asset(row['path']),'caption_exact':row['caption'],'caption_csv_local':str(csvpath),'caption_csv_sha256':sha(csvpath),'human_to_human_release_subset':row['action'] in acts})
write('FLEXIACT_ALL_89_PAIRS.json',{'revision':rev,'count':89,'pairs':pairs})
h=[x for x in pairs if x['human_to_human_release_subset']];assert len(h)==39
for x in h:assert x['source']['downloaded'] and x['target']['downloaded']
write('FLEXIACT_HUMAN_39_PAIRS.json',{'revision':rev,'independent_source_count':5,'pair_count':39,'unique_target_count':20,'source_counts':{a:sum(x['action']==a for x in h) for a in acts},'pairs':h})
pts=[]
for a in acts:
 v=downloaded[f'benchmark/reference_videos/human/{a}.mp4'];j=json.loads(subprocess.run(['ffprobe','-v','error','-select_streams','v:0','-show_frames','-show_entries','frame=best_effort_timestamp,best_effort_timestamp_time','-of','json',v['local_path']],capture_output=True,text=True,check=True).stdout);times=[float(x['best_effort_timestamp_time']) for x in j['frames']];assert len(times)==49 and times[0]==0 and times[-1]==6.0 and all(abs(times[i]-i/8)<1e-9 for i in range(49));pts.append({'action':a,'source_sha256':v['sha256'],'probe':v['probe'],'frames':j['frames'],'pts_zero_origin_8fps_exact':True})
write('FLEXIACT_SOURCE_TIMEBASE.json',{'sources':pts,'all_49frames_8fps':True,'sample_span_seconds':6.0,'container_duration_seconds':6.125,'H3_frame_grid':'UNDECIDED_ROOT_TO_FREEZE_NO_IMPLICIT_TRUNCATION_OR_SPEED_CHANGE'})
protocol={'schema':'h3_public_benchmark_source_only_plan_v1','date':'2026-10-17','status':'SOURCE_ASSETS_AND_PAIR_SET_FROZEN; H3_TIME_GRID_AND_SCORER_ENV_PENDING','priority':'FlexiAct full human-to-human released subset; MTBench stable first6 source-only eligible as supplement','generation_not_executed':True,'evaluation_not_executed':True,'source_results_used_for_selection':False,'generative_results_seen':False,'dataset_revision':rev,'official_code_commit':json.loads((S/'flexiact_tree.txt').read_text())['sha'],'full_release_denominator':{'official_reference_actions':15,'official_val_csv_rows':89,'paper_claimed_pairs_not_reconciled_to_release':250},'primary_denominator':{'actions':acts,'independent_sources':5,'pairs':39,'unique_targets':20,'failed_or_unknown_pairs_retained':True},'pilot':{'count':5,'selection':'first row in each of the five original val_image.csv files; order=actions','stable_ids':[next(x['stable_id'] for x in h if x['action']==a) for a in acts],'after_pilot':'complete all remaining34 without H3-result filtering'},'input':{'reference_video':'original published MP4, full49 frames; unmodified assets','identity_image':'exact original paired target image, not substituted Sam','caption':'exact original CSV string; any H3 wrapper text documented as explicit adaptation','H3_duration_fps_geometry':'not selected here; root must freeze a legal grid preserving entire motion and record source→output PTS; no implicit141 crop/tail freeze/time stretch','source_timing_resolution_ms':125,'do_not_claim_24fps_2frame_precision':True},'scoring':{'author_code':'pinned original MF + optional original quality metrics; no silent numeric repairs','supplement':'signed physical action-time difference, ms + original-frame + output-frame units, full support/UNKNOWN; same-time identity/shape review','no_temporal_alignment_before_time_score':True,'nan_and_failure':'retain raw exception/nonfinite status and denominator; cannot silently exclude','aggregation':'report39 per-pair; five source means equally weighted; separate official-source motions from targets','not_original_leaderboard_if_adapted':True},'MTBench_supplement':{'mother_set':100,'prompts':500,'selection':'after complete source-only eligibility ledger, bytewise stable source ID first6 eligible; no H3-result-based selection','eligibility':'single intended human subject, continuous shot, upper-body evidence, readable timestamps; missing evidence UNKNOWN; do not infer from three thumbnails alone','stable_first6_ids':'PENDING_FULL_SOURCE_ONLY_ELIGIBILITY','timegrid':'also pending; 90sources8fps/5sources10fps/5sources14fps'},'license':{'HF_card':'MIT','repo':'Apache-2.0','underlying_movie_game_image_rights':'not independently established; preserve source attribution, no unrestricted-redistribution claim'},'pending_before_any_score':['root H3 temporal/spatial adaptation choice','official scorer isolated environment/checkpoint pinning and finite-score smoke','source-only visual eligibility evidence for MTBench','precise versioned output naming/method/seed schedule'], 'evidence':{n:sha(P/n) for n in ['FLEXIACT_ALL_89_PAIRS.json','FLEXIACT_HUMAN_39_PAIRS.json','FLEXIACT_ASSET_DOWNLOAD_PLAN.json','FLEXIACT_ASSET_HEAD.json','FLEXIACT_ASSET_RECEIPT.json','FLEXIACT_SOURCE_TIMEBASE.json']}}
write('PROTOCOL.json',protocol)
print(json.dumps({'pair_count':len(pairs),'human_pairs':len(h),'sources':len(pts),'pilot':protocol['pilot']['stable_ids'],'all25_assets_lfs_exact':all(x['lfs_exact'] for x in receipt['files'])}))
